    private Course createCourse(String title, String slug, String description, String category, String duration, double price, String badgeColor, String objectives) {
        Course c = new Course();
        c.setTitle(title);
        c.setSlug(slug);
        c.setDescription(description);
        c.setCategory(category);
        c.setDuration(duration);
        c.setPrice(price);
        c.setBadgeColor(badgeColor);
        c.setLearningObjectives(objectives);
        c.setPublished(true);
        return courseRepository.save(c);
    }

    private Assessment createAssessment(Course course, String title, String description, int timeLimit, int passPercent) {
        Assessment a = new Assessment();
        a.setCourse(course);
        a.setTitle(title);
        a.setDescription(description);
        a.setTimeLimitMinutes(timeLimit);
        a.setPassPercentage(passPercent);
        return assessmentRepository.save(a);
    }

    private void createQuestion(Assessment assessment, String text, Question.QuestionType type, List<String> options, String correct, String explanation) {
        Question q = new Question();
        q.setAssessment(assessment);
        q.setQuestionText(text);
        q.setQuestionType(type);
        try {
            q.setOptionsJson(objectMapper.writeValueAsString(options));
        } catch (Exception ignored) {}
        q.setCorrectAnswer(correct);
        q.setExplanation(explanation);
        questionRepository.save(q);
    }

    private void cq(Assessment a, String text, List<String> options, String correct, String explanation) {
        createQuestion(a, text, Question.QuestionType.MCQ, options, correct, explanation);
    }

    private boolean seedQuestionsFromJson(Assessment a, String filename) {
        try {
            var is = getClass().getResourceAsStream("/questions/" + filename);
            if (is == null) {
                is = getClass().getClassLoader().getResourceAsStream("questions/" + filename);
            }
            if (is != null) {
                com.fasterxml.jackson.databind.JsonNode root = objectMapper.readTree(is);
                if (root.isArray() && root.size() > 0) {
                    for (com.fasterxml.jackson.databind.JsonNode node : root) {
                        String qText = node.path("questionText").asText();
                        List<String> options = new java.util.ArrayList<>();
                        for (com.fasterxml.jackson.databind.JsonNode opt : node.path("options")) {
                            options.add(opt.asText());
                        }
                        String correct = node.path("correctAnswer").asText();
                        String explanation = node.path("explanation").asText();
                        cq(a, qText, options, correct, explanation);
                    }
                    System.out.println(">>> Loaded " + root.size() + " genuine questions from " + filename + " for " + a.getTitle());
                    return true;
                }
            }
        } catch (Exception e) {
            System.err.println("Failed to load questions from " + filename + ": " + e.getMessage());
        }
        return false;
    }

    /**
     * Safe, read-only verification of question counts on startup.
     * This method NEVER deletes, overwrites, or replaces any existing questions.
     * It only logs the current state for operational visibility.
     */
    private void verifyQuestionCounts() {
        try {
            List<Assessment> assessments = assessmentRepository.findAll();
            int totalQuestions = 0;
            for (Assessment a : assessments) {
                long count = questionRepository.findByAssessmentId(a.getId()).size();
                totalQuestions += count;
                String courseTitle = (a.getCourse() != null) ? a.getCourse().getTitle() : "Unknown";
                System.out.println(">>> [Startup Check] " + courseTitle + ": " + count + " questions");
            }
            System.out.println(">>> [Startup Check] Total questions across all assessments: " + totalQuestions);
        } catch (Exception e) {
            System.err.println("Error during startup question verification: " + e.getMessage());
        }
    }

    private void seedCourseContent(Course course, List<ModuleSeed> moduleSeeds) {
        int mOrder = 1;
        for (ModuleSeed ms : moduleSeeds) {
            Module m = new Module(course, ms.title, mOrder++);
            m = moduleRepository.save(m);

            int lOrder = 1;
            for (LessonSeed ls : ms.lessons) {
                Lesson l = new Lesson();
                l.setModule(m);
                l.setTitle(ls.title);
                l.setLessonType(ls.type);
                l.setContent(ls.content);
                l.setDurationMinutes(ls.duration);
                l.setLessonOrder(lOrder++);
                l.setVideoUrl("https://www.youtube.com/embed/dQw4w9WgXcQ");
                l.setPdfUrl("/assets/sample_guide.pdf");
                lessonRepository.save(l);
            }
        }
    }

